from comun import *
D = Doc('Manual explicativo de resultados', 'Qué significan los números de la encuesta, en palabras simples y con ejemplos de todos los días', 'PRODUCTO F · GUÍA PARA PÚBLICO NO ESPECIALIZADO', G + 'portada_puerta.png', 'Proyecto La Puerta · Manual explicativo de resultados')
g = R['global']; O = OF; fo = {r['var']: r for r in O['filas']}; S = O['semaforo_estudiantes']; h4 = R['H4']; h5 = R['H5']

intro(D, 'La interpretación, en lenguaje cotidiano, de los resultados de la encuesta de percepción y competencias del Proyecto La Puerta (n = 184).',
 'Los informes técnicos usan términos estadísticos que dificultan su uso por docentes, jefaturas, empresas y estudiantes. Este manual traduce los resultados y los acompaña con ejemplos de todos los días.',
 'Explicar los resultados de la encuesta a un público no especializado, de modo que pueda interpretarlos y usarlos para decidir.',
 ['Entregar ideas básicas para leer números sin errores.', 'Interpretar cada resultado principal con una ficha estándar.', 'Señalar las implicancias para cada actor.', 'Responder preguntas frecuentes y definir los términos.'],
 'El documento se organiza en cinco partes: la Introducción (cómo usar el manual); el Desarrollo (ideas para leer números, fichas de resultados, implicancias, preguntas frecuentes y glosario); la Conclusión (lista de verificación antes de citar un resultado); las Referencias; y los Anexos (declaración de uso de IA).')
D.h1('Cómo usar este manual')
D.p('Este manual está escrito para quien **no es estadístico ni investigador**: directoras y directores de carrera, docentes, tutores de empresas, equipos de apoyo y también estudiantes. Explica, resultado por resultado, **qué se encontró, qué significa en simple y qué implica** para quien debe tomar decisiones.')
D.p('No necesita leerlo de corrido. Puede ir directo a la **ficha** que le interesa (Sección 3) y volver a la Sección 2 si alguna palabra le queda dudosa. Cada ficha tiene la misma estructura:')
D.table(['Parte de la ficha', 'Qué responde'], [['**Lo que muestran los datos**', 'La cifra o hallazgo, sin adornos.'], ['**Dicho simple**', 'Qué quiere decir en lenguaje cotidiano.'], ['**Un ejemplo de todos los días**', 'Una comparación que ayuda a imaginarlo.'], ['**Qué implica para la organización**', 'Qué decisión o conversación abre.'], ['**Cuánta confianza darle**', 'Qué tan sólido es el hallazgo: alta, media o baja.']], [5.2, 11.4], size=9.5)
D.callout('De dónde vienen los números', f"Una encuesta confidencial respondida por **{N} estudiantes** de Duoc UC Sede San Bernardo entre el 13 y el 16 de octubre de 2026. Cada persona dijo qué tan de acuerdo estaba (de 1 a 5) con 15 afirmaciones sobre su preparación para el trabajo y respondió dos preguntas abiertas. **Son opiniones sobre uno mismo**, no pruebas ni evaluaciones de desempeño.", SKY, 'EEF4FB')
aviso_datos(D)

D.part('DESARROLLO')
D.h1('2. Siete ideas para leer números sin enredarse')
ideas = [
 ('1. La escala de 1 a 5', 'Cada afirmación se respondió así: **1** = muy en desacuerdo, **2** = en desacuerdo, **3** = ni de acuerdo ni en desacuerdo, **4** = de acuerdo, **5** = muy de acuerdo.', 'Es como calificar un restaurante con estrellas: un 4 significa «bien», un 5 «excelente», un 3 «ni fu ni fa».'),
 ('2. El promedio', 'Suma de todas las respuestas dividida por el número de personas. Resume en un solo número qué tan de acuerdo estuvo el grupo.', 'Si cinco amigos califican una película con 5, 4, 4, 3 y 4, el promedio es 4,0. Pero ese 4,0 no muestra que alguien puso 3.'),
 ('3. El porcentaje de acuerdo', 'Es el porcentaje de personas que respondió **4 o 5**. Es la cifra más fácil de entender y por eso la usamos para el semáforo.', 'Si de 100 personas, 70 dicen «de acuerdo» o «muy de acuerdo», el porcentaje de acuerdo es 70 %.'),
 ('4. La meta de 70 %', 'Usamos 70 % como meta por analogía con la **exigencia del 70 %** que se aplica en las rúbricas de Duoc: se espera que la mayoría —no solo la mitad— esté de acuerdo.', 'Es como pedir 70 % de logro para dar por aprobada una evaluación.'),
 ('5. El margen de error', 'Como solo respondieron algunos estudiantes y no todos, el número exacto podría ser algo distinto si preguntáramos a otro grupo. El margen de error es el «más o menos» alrededor del promedio.', 'Es como la balanza de la feria: marca 1 kilo, pero podría ser 980 o 1.020 gramos. Si dos marcas se traslapan, no hay diferencia clara.'),
 ('6. Diferencia grande o pequeña, y diferencia «significativa»', 'Una diferencia puede ser **real pero pequeña**, o **grande pero poco confiable** si hay pocas personas. «Significativa» solo quiere decir «es difícil que sea casualidad»; **no** quiere decir «importante».', f"Diferencia de {n(fo['GLOBAL']['dif'])} puntos (con vs. sin práctica) en una escala de 1 a 5: es como pasar de un 4,0 a un 4,17. Se nota poco."),
 ('7. Relación no es causa', 'Que dos cosas vayan juntas (por ejemplo, saber cómo es el trabajo y sentirse seguro) no prueba que una cause la otra. Puede haber una tercera cosa detrás, o que sea al revés.', 'Las personas que llevan paraguas y las que se mojan suelen coincidir: el paraguas no causa la lluvia.')]
for t, a, b in ideas:
    D.h3(t); D.p(a); D.p('**Ejemplo cotidiano:** ' + b, 9.8, GRAY)

D.h1('3. Los resultados, uno por uno (fichas)')
def ficha(titulo, datos, simple, ejemplo, implica, conf, color=TEAL, fig=None, cap=None, w=15):
    D.h2(titulo)
    if fig: D.fig(fig, cap, w)
    t = D.d.add_table(rows=0, cols=2); borders(t)
    for lab, txt, c in (('Lo que muestran los datos', datos, NAVY), ('Dicho simple', simple, NAVY), ('Un ejemplo de todos los días', ejemplo, NAVY), ('Qué implica para la organización', implica, NAVY), ('Cuánta confianza darle', conf, NAVY)):
        r = t.add_row(); keep_row(r); a, b = r.cells; shade(a, 'F3F6FA'); cell_margins(a); cell_margins(b)
        runs(a.paragraphs[0], lab, 9.2, c, bold=True); runs(b.paragraphs[0], txt, 9.8)
        a.paragraphs[0].paragraph_format.space_after = Pt(0); b.paragraphs[0].paragraph_format.space_after = Pt(0)
        if lab != 'Cuánta confianza darle': a.paragraphs[0].paragraph_format.keep_with_next = True; b.paragraphs[0].paragraph_format.keep_with_next = True
    set_col_widths(t, [4.2, 12.4]); D.d.add_paragraph().paragraph_format.space_after = Pt(4)

ficha('Ficha 1 · El puntaje global', f"Promedio global **{n(g['media'])}** de 5 (margen de error: {n(g['ci'][0])} a {n(g['ci'][1])}). El 70 % de todas las respuestas fue «de acuerdo» o «muy de acuerdo» y solo el 9 % «en desacuerdo».", 'Los estudiantes, en general, se sienten bastante preparados. No es un resultado sobresaliente (que sería 4,2 o más), pero tampoco preocupante (menos de 3,5).', 'Es como un curso con nota promedio 5,3 en escala de 1 a 7: «va bien», con espacio para subir.', 'Hay una base para construir. Lo que corresponde es mejorar puntos específicos, no rehacer todo.', 'Alta.', TEAL, 'g04_global_hist', 'Cómo se distribuye el puntaje global.', 11)
ficha('Ficha 2 · Las fortalezas', f"Más de 80 % de acuerdo en: dialogar y lograr acuerdos en equipo (**{pc(IT['P07']['fav'])}**), mantener la ética bajo presión (**{pc(IT['P14']['fav'])}**), querer proyectos con empresas (**{pc(IT['P15']['fav'])}**), confiar ante una tarea nueva (**{pc(IT['P03']['fav'])}**) y saber cuándo actuar solo o consultar (**{pc(IT['P08']['fav'])}**).", 'Los estudiantes llegan con buena **actitud**: dispuestos a conversar, a aprender, a hacer las cosas bien.', 'Es como un equipo de fútbol con buenas ganas y buen compañerismo: falta pulir la técnica, pero la base humana está.', 'Se puede apostar a metodologías participativas y de equipo; las quejas por «falta de actitud» no tienen respaldo en estos datos.', 'Alta (son opiniones, no conductas observadas).')
ficha('Ficha 3 · Conocer el trabajo «de verdad»', f"Menos de 70 % de acuerdo en: conocer las tareas reales (**{pc(IT['P01']['fav'])}**), las exigencias de las empresas (**{pc(IT['P02']['fav'])}**), haber comprobado si el trabajo calza con sus intereses (**{pc(IT['P09']['fav'])}**) y elegir el método adecuado para la empresa (**{pc(IT['P06']['fav'])}**).", 'Se sienten capaces, pero **aún no han visto lo suficiente del trabajo real** para tener certeza.', 'Es como alguien que aprendió a manejar en un simulador: se siente capaz, pero todavía no ha salido a la calle.', 'Priorizar actividades que acerquen la realidad laboral: visitas, simulaciones, casos con empresas, tutores de empresa que cuenten su día a día.', 'Alta para el dato; media para la explicación.', AMB)
ficha('Ficha 4 · La red de contactos', f"Solo **{pc(IT['P12']['fav'])}** dice tener una red de contactos laborales a quienes recurrir; **{pc(IT['P12']['des'])}** dice que no. Es la afirmación más baja de las 15 y **es significativamente menor que cada una de las otras 14**. Sucede con y sin práctica previa y en todos los años.", 'Más de la mitad de los estudiantes **no tiene a quién preguntar** cuando quiere saber cómo es un trabajo o cómo conseguir una práctica.', 'Es como llegar a una ciudad nueva sin conocer a nadie: se puede salir adelante, pero se pierden recomendaciones, información y oportunidades.', 'Es la brecha más clara. Conviene crear **puentes** con egresados, empresas socias y profesionales desde el primer año (mentorías, charlas, ferias).', 'Alta.', CORAL, 'g16_redes', 'Interés alto, red baja.', 13)
ficha('Ficha 5 · Querer vs. tener', f"Quieren participar en proyectos con empresas reales (**{pc(IT['P15']['fav'])}**), pero no tienen la red para hacerlo (P12: {pc(IT['P12']['fav'])}). Por eso el promedio de la dimensión de redes (3,72) **esconde dos realidades opuestas**.", 'Hay **ganas de sobra** y **pocos puentes**. El problema no es motivación: es acceso.', 'Es como tener hambre en una casa sin cocina: el apetito existe, falta la forma de satisfacerlo.', 'Las iniciativas tipo La Puerta tienen una demanda ya instalada. Además, en la próxima encuesta conviene separar «interés» de «red».', 'Alta.')
ficha('Ficha 6 · Práctica previa: ¿hace diferencia?', f"Quienes ya hicieron una práctica puntúan **{n(fo['GLOBAL']['con'])}** y quienes no **{n(fo['GLOBAL']['sin'])}**: una diferencia de **{n(fo['GLOBAL']['dif'])}**. El proyecto esperaba una diferencia de 0,8 a 1,2 puntos. La diferencia observada es **pequeña y no concluyente**.", 'La práctica previa **ayuda un poco**, pero no es lo que separa a quienes se sienten preparados de quienes no.', 'Es como la ventaja de haber probado antes un deporte: ayuda a partir, pero lo que decide es cuánto se practica y cómo.', 'No conviene tratar a las personas «sin práctica previa» como un grupo de riesgo por esa sola razón. Es mejor mirar quién está en semáforo rojo y qué brechas concretas tiene.', 'Media (efecto pequeño; la muestra no permite ser tajante).', AMB, 'g06_practica', 'Con y sin práctica previa, por dimensión.', 13)
ficha('Ficha 7 · El año de estudio', f"No hay una escalera que suba semestre a semestre. El tramo 3.º–4.º semestre es el más bajo ({n(H2['GLOBAL']['medias'][1])}), y 5.º semestre o más el más alto ({n(H2['GLOBAL']['medias'][2])}), pero estas diferencias **no son confiables** estadísticamente.", 'Avanzar de semestre **por sí solo** no hace que los estudiantes se sientan más preparados.', 'Es como un curso de natación: pasar los meses no basta; hay que meterse al agua.', 'Una hipótesis a observar: un «valle» a mitad de carrera. No es un hecho; hay que mirarlo en la próxima medición.', 'Baja.', CORAL)
ficha('Ficha 8 · El semáforo', f"Con los cortes oficiales del proyecto (verde 4,20 o más; amarillo 3,50 a 4,19; rojo menos de 3,50): **{pc(S['pct_total']['Verde'])}** verde, **{pc(S['pct_total']['Amarillo'])}** amarillo y **{pc(S['pct_total']['Rojo'])}** rojo ({S['total']['Rojo']} personas). Rojos: 14 % con práctica previa y 25 % sin práctica.", 'Cerca de **uno de cada cinco** estudiantes tiene una autopercepción baja y podría necesitar acompañamiento antes de la práctica.', 'Es como una alerta preventiva de salud: no es un diagnóstico, sino una señal para mirar con más atención.', 'Conviene acompañar a ese grupo con tutoría y actividades específicas, y revisar las respuestas de cada persona antes de la práctica.', 'Media-alta (depende de cómo se fijen los cortes).', AMB, 'g22_semaforo_oficial', 'Semáforo oficial, con y sin práctica previa.', 12)
ficha('Ficha 9 · Lo que se asocia con sentirse seguro', f"La seguridad de poder adaptarse a un puesto se relaciona **moderada a fuertemente** con conocer las tareas reales, saber aplicar lo aprendido y haber comprobado si el trabajo calza (correlaciones de 0,47 a 0,53). Estos factores juntos explican cerca del **{pc(100*h4['ols']['r2'])}** de las diferencias. **Haber tenido práctica previa deja de importar** cuando se consideran esos factores.", 'Más que «haber tenido una práctica», parece contar **qué se aprendió o vio en ella**.', 'Dos personas que trabajaron un verano: la que preguntó, observó y probó tareas sale más segura que la que solo cumplió horario.', 'Si esto se confirma, actividades breves y bien diseñadas que muestren el trabajo real podrían dar parte del beneficio a todos, sin esperar la práctica completa.', 'Media (es una asociación; no prueba causa).', SKY, 'g13_h4', 'Qué factores pesan más para sentirse seguro de adaptarse.', 12.5)
ficha('Ficha 10 · Lo que cuentan con sus propias palabras', f"De {Q['abi1_n']} respuestas sobre el aprendizaje más valioso, el tema más repetido es **habilidades blandas** ({Q['abi1']['Habilidades blandas (equipo, comunicación, responsabilidad, adaptación)']}): trabajo en equipo, comunicación, responsabilidad. {Q['abi1']['Sin aprendizaje claro / no sabe']} personas dijeron **no tener un aprendizaje claro** y {Q['abi1_por_practica']['Sin aprendizaje claro / no sabe']['sin']} de ellas no tienen práctica previa.", 'Valoran sobre todo lo humano del trabajo; y quien aún no ha tenido contacto con el trabajo real siente que **no tiene experiencia que contar**.', 'Es como la diferencia entre leer sobre cocinar y haber cocinado una vez: quien ya lo hizo tiene una anécdota que contar.', 'Todo estudiante debería tener, antes de la práctica, al menos una vivencia concreta de trabajo real sobre la cual reflexionar.', 'Media (clasificación temática preliminar).', SKY, 'g10_abi1', 'Temas del aprendizaje más valioso.', 13.5)
ficha('Ficha 11 · El apoyo que piden', f"De {Q['abi2_n']} respuestas: lo más pedido son **simulaciones y práctica aplicada** ({Q['abi2']['Simulaciones, casos reales y práctica aplicada']}), **comunicación y oratoria** ({Q['abi2']['Comunicación, oratoria y habilidades blandas']}), **inglés** ({Q['abi2']['Idiomas (inglés principalmente)']}), **preparación para la práctica y el empleo** ({Q['abi2']['Preparación para la práctica y el empleo (entrevista, CV, inducción, apoyo)']}), **software como ERP y Excel** ({Q['abi2']['Software y herramientas (ERP, SAP, Softland, Excel, Python, Power BI, IA)']}) y **salidas a terreno** ({Q['abi2']['Salidas a terreno, visitas, ferias y charlas']}).", 'Piden **práctica antes de la práctica**: ensayar, ver y usar herramientas reales.', 'Es como pedir un ensayo general antes del estreno de la obra.', 'Es una lista de actividades concretas y bien definidas para diseñar el programa de apoyo (ver Manual de propuestas de mejora).', 'Alta para el tema; media para el conteo exacto.', SKY, 'g11_abi2', 'Temas del apoyo solicitado.', 13.5)
ficha('Ficha 12 · Lo que todavía no sabemos', 'Si el programa La Puerta **cambia** algo. La base no trae el código del estudiante, el momento (antes/después), el grupo (La Puerta/comparación) ni la valoración del programa; tampoco las preguntas A03 y A04 del informe metodológico.', 'Hoy sabemos **cómo están** los estudiantes, no **si el programa los hizo mejorar**.', 'Es como tener una foto: se ve cómo está la persona hoy, pero no se sabe si hace un año estaba peor o mejor.', 'Antes de la próxima aplicación hay que registrar esos cuatro datos. Es barato y es lo que permitirá demostrar el impacto.', 'No aplica: es una limitación.', CORAL, 'g20_diseno_futuro', 'Qué falta para medir el efecto del programa.', 14.5)

D.h1('4. Qué significa esto para cada persona')
D.table(['Si usted es…', 'Lo que conviene que sepa', 'Lo que puede hacer'], [
 ['**Estudiante**', 'La mayoría de sus compañeros se siente capaz, pero casi nadie tiene una red de contactos. No está solo/a con esa sensación.', 'Aprovechar charlas, visitas y ferias; hacer preguntas a docentes y profesionales; registrar lo que aprende en cada actividad con empresas.'],
 ['**Docente**', 'Piden clases más aplicadas, con casos y herramientas reales. Aprecian los casos que cuentan docentes con experiencia en empresas.', 'Incluir casos reales, invitar a profesionales, usar simulaciones breves; explicar para qué sirve cada herramienta en el trabajo.'],
 ['**Jefatura de carrera**', 'El 21 % está en semáforo rojo. El tramo de 3.º–4.º semestre merece atención. La práctica previa, por sí sola, no define quién necesita apoyo.', 'Identificar a quienes están en rojo; planificar salidas, mentorías y talleres; coordinar con empresas socias.'],
 ['**Dirección de Escuela**', 'Hay una demanda amplia (83 %) de proyectos con empresas, y una brecha clara en redes. La evaluación del programa requiere corregir la medición.', 'Asegurar recursos para el piloto con medición antes/después; definir responsables; decidir el escalamiento solo con evidencia comparada.'],
 ['**Empresa socia / tutor**', 'Los estudiantes llegan con buena actitud y quieren vincularse, pero conocen poco el día a día laboral.', 'Ofrecer visitas, charlas cortas, proyectos acotados y orientación en el primer día de práctica.']], [3.2, 6.7, 6.7], size=9)

D.h1('5. Preguntas frecuentes')
faq = [
 ('¿Qué tan confiables son estos resultados?', f"La encuesta es consistente internamente (alfa de Cronbach = {n(g['alpha'])}, que es alto) y tiene pocos datos faltantes (2 %). Pero son **opiniones de una sola vez**, de personas que **eligieron responder**. Son una buena fotografía, no un veredicto."),
 ('¿Por qué no se puede decir si La Puerta funciona?', 'Porque para saberlo hay que comparar a las mismas personas **antes y después**, y con un grupo parecido que no participó. En la base esos datos están vacíos. Es corregible.'),
 ('Si la diferencia con práctica previa es tan pequeña, ¿la práctica previa no sirve?', f"Sí sirve, un poco: puntúan {n(fo['GLOBAL']['dif'])} puntos más. Lo que no se sostiene es que sea una diferencia enorme. Además, lo que parece pesar más es **lo que se aprendió** en la práctica."),
 ('¿Por qué algunas diferencias «se ven» pero no son «significativas»?', 'Porque con grupos pequeños el azar puede producir diferencias aparentes. Para no confundirnos, se usan pruebas que dicen cuán probable es que sea casualidad, y se corrigen cuando se hacen muchas comparaciones.'),
 ('¿El 21 % en rojo son estudiantes «con problemas»?', 'No. Es un grupo cuyo **puntaje autopercibido** es bajo. Puede deberse a poca experiencia, nervios o simple modestia. Es una señal para acompañar, no una etiqueta.'),
 ('¿Se puede generalizar a toda Duoc UC?', 'No. El 98 % de las respuestas es de la Escuela de Administración y Negocios y la participación fue voluntaria. Sirve para esta escuela y sede.'),
 ('¿Por qué «No sé / No aplica» no se cuenta?', 'Porque no es una opinión sobre el tema. Fueron pocas (2 %) y no cambian los resultados.'),
 ('¿Qué hago si un resultado me parece raro?', 'Revise la ficha y la advertencia de confianza. Si sigue dudando, pida la verificación: el análisis puede repetirse con el código del repositorio.'),
 ('¿Quién clasificó las respuestas abiertas?', 'Una herramienta de IA, con revisión preliminar. Debe ser validada por una persona; hasta entonces, trate los conteos como aproximados.'),
 ('¿Cuándo deberíamos repetir la encuesta?', 'Al inicio y al final del semestre en que se aplique La Puerta, con código único, momento y grupo, para medir cambios reales.')]
for q, a in faq:
    D.h3(q); D.p(a)

D.h1('6. Glosario')
gl = [('Alfa de Cronbach', 'Número entre 0 y 1 que indica si las afirmaciones de una encuesta «van en la misma dirección». Sobre 0,70 es aceptable.'), ('Autoeficacia', 'Creer que uno es capaz de lograr una tarea. Se fortalece con experiencias de logro.'), ('Autopercepción', 'Lo que una persona cree de sí misma. No es lo mismo que su desempeño observado.'),
 ('Brecha', 'Distancia entre lo observado y lo esperado (por ejemplo, la meta de 70 %).'), ('Correlación (rho, r)', 'Mide cuánto «van juntas» dos cosas, de −1 a +1. Cerca de 0 = casi nada; 0,3 = moderada; 0,5 = fuerte.'), ('Dimensión', 'Grupo de afirmaciones que miden una misma idea (por ejemplo, redes).'),
 ('Diferencia significativa', 'Diferencia que difícilmente se debe al azar. No significa «importante».'), ('Efecto (tamaño del)', 'Qué tan grande es una diferencia, independientemente de cuántas personas se midieron.'), ('Escala Likert', 'Escala de acuerdo/desacuerdo, aquí de 1 a 5.'),
 ('Estudio transversal', 'Medición hecha una sola vez, como una fotografía.'), ('Grupo de comparación (control)', 'Grupo parecido que no participa en la intervención y permite ver qué habría ocurrido sin ella.'), ('Intervalo de confianza', 'Rango en el que probablemente está el valor real. Equivale al «más o menos».'),
 ('Línea base', 'Medición inicial, contra la cual se compara después.'), ('Muestra voluntaria', 'Grupo que respondió porque quiso; puede ser distinto de quienes no respondieron.'), ('Percentil / mediana', 'La mediana es el valor central: la mitad está sobre ella y la mitad bajo ella.'),
 ('Pretest / postest', 'Medición antes y después de una intervención.'), ('Semáforo', 'Clasificación en verde, amarillo y rojo según puntajes.'), ('Shock de transición', 'Dificultad inicial al pasar de estudiar a trabajar.'), ('Valor p', 'Probabilidad de ver una diferencia así si en realidad no hubiera ninguna. Menor a 0,05 se suele considerar «significativa».'), ('Variable', 'Cualquier característica que se mide (por ejemplo, año de estudio).')]
D.table(['Término', 'Qué significa'], gl, [4.2, 12.4], size=9.3)

D.part('CONCLUSIÓN')
D.h1('Antes de citar un resultado: lista de verificación')
D.callout('Cinco preguntas antes de usar una cifra en un documento o una reunión', ['**1. ¿Es una opinión o un hecho?** Casi todo aquí son opiniones de los propios estudiantes.', '**2. ¿Es una diferencia pequeña o grande?** Mire el tamaño, no solo si es «significativa».', '**3. ¿Con quiénes se compara?** Evite comparar grupos muy distintos en tamaño (por ejemplo, 5 personas).', '**4. ¿Se está diciendo «causa» donde solo hay «relación»?** Cuide el verbo: «se asocia con», no «provoca».', '**5. ¿Se cita la limitación?** Una sola medición, muestra voluntaria, 98 % de una escuela.'], AMB, 'FFF7E0')
bibliografia(D, [1, 5, 13, 15, 16, 18, 0, 7, 19, 20])
D.part('ANEXOS')
D.h1('Declaración de uso de IA y fuentes')
declaracion_ia(D, 'traducir los resultados técnicos a lenguaje cotidiano, proponer ejemplos y organizar el manual')
D.save('/home/user/Perfil_investigador/La_Puerta_Informes/informes/F_Manual_Explicativo_Resultados.docx'); print('F ok')
